#!/bin/bash

# Script de déploiement Sphorix France Phase 1
# Usage: bash scripts/deploy-phase1.sh [local|preview|production]

set -e

ENVIRONMENT=${1:-local}
PROJECT_ROOT=$(dirname "$(dirname "$(readlink -f "$0")")")

echo "🚀 Déploiement Sphorix France - Phase 1"
echo "📍 Environnement: $ENVIRONMENT"
echo ""

# Couleurs
RED='\033[0;31m'\nGREEN='\033[0;32m'\nYELLOW='\033[1;33m'\nNC='\033[0m' # No Color

# Fonctions
print_section() {\n  echo -e \"${GREEN}▶ $1${NC}\"\n}\n\nprint_error() {\n  echo -e \"${RED}✗ $1${NC}\"\n}\n\nprint_success() {\n  echo -e \"${GREEN}✓ $1${NC}\"\n}\n\nprint_warning() {\n  echo -e \"${YELLOW}⚠ $1${NC}\"\n}\n\n# Étape 1: Vérification des variables d'environnement\nprint_section \"1. Vérification variables d'environnement\"\n\nrequired_vars=(\"STRIPE_SECRET_KEY\" \"STRIPE_WEBHOOK_SECRET\" \"NEXT_PUBLIC_SITE_URL\")\nfor var in \"${required_vars[@]}\"; do\n  if [ -z \"${!var}\" ]; then\n    print_error \"Variable manquante: $var\"\n    exit 1\n  fi\ndone\n\nif [ \"$ENVIRONMENT\" != \"local\" ]; then\n  smtp_vars=(\"SMTP_HOST\" \"SMTP_PORT\" \"SMTP_USER\" \"SMTP_PASS\")\n  for var in \"${smtp_vars[@]}\"; do\n    if [ -z \"${!var}\" ]; then\n      print_error \"Variable SMTP manquante: $var\"\n      exit 1\n    fi\n  done\nfi\n\nprint_success \"Toutes les variables d'environnement présentes\"\necho \"\"\n\n# Étape 2: Installation dépendances\nif [ \"$ENVIRONMENT\" = \"local\" ]; then\n  print_section \"2. Installation des dépendances\"\n  if [ ! -d \"node_modules\" ]; then\n    npm install\n  fi\n  print_success \"Dépendances OK\"\n  echo \"\"\nfi\n\n# Étape 3: Build\nprint_section \"3. Build du projet\"\nnpm run build\nif [ $? -eq 0 ]; then\n  print_success \"Build réussi\"\nelse\n  print_error \"Build échoué\"\n  exit 1\nfi\necho \"\"\n\n# Étape 4: Lint & tests\nif [ \"$ENVIRONMENT\" = \"local\" ]; then\n  print_section \"4. Validation code (ESLint + tests)\"\n  npm run lint\n  npm run test\n  print_success \"Validation code OK\"\n  echo \"\"\nfi\n\n# Étape 5: Migrations Supabase\nif [ \"$ENVIRONMENT\" = \"local\" ]; then\n  print_section \"5. Migrations Supabase\"\n  print_warning \"Exécuter manuellement: supabase db reset ou supabase db push\"\n  echo \"\"\nfi\n\n# Étape 6: Checklist pré-déploiement\nprint_section \"6. Checklist pré-déploiement\"\necho \"\"\necho \"   Configuration Stripe:\" \necho \"     ☐ Mode test activé (cartes de test)\"\necho \"     ☐ Webhook configuré: /api/stripe/webhook\"\necho \"     ☐ STRIPE_SECRET_KEY correcte\"\necho \"     ☐ STRIPE_WEBHOOK_SECRET correcte\"\necho \"\"\necho \"   Configuration SMTP:\"\necho \"     ☐ SMTP_HOST configuré\"\necho \"     ☐ SMTP_USER et SMTP_PASS valides\"\necho \"     ☐ SMTP_FROM est un email du domaine\"\necho \"\"\necho \"   Base de données:\"\necho \"     ☐ Migration stripe_enhancements appliquée\"\necho \"     ☐ Tables: payment_events, orders modifiées\"\necho \"\"\necho \"   Pages légales:\"\necho \"     ☐ /cgv accessible\"\necho \"     ☐ /politique-remboursement accessible\"\necho \"     ☐ /politique-confidentialite existante\"\necho \"\"\necho \"   Sécurité:\"\necho \"     ☐ Pas de credentials en dur dans le code\"\necho \"     ☐ Variables d'env en .env.local (dev) ou Vercel (prod)\"\necho \"     ☐ Webhooks Stripe signés\"\necho \"\"\n\nread -p \"Appuyez sur Enter pour continuer...\"\n\necho \"\"\nprint_section \"Checklist pré-déploiement\"\necho \"✅ Déploiement prêt!\"\necho \"\"\necho \"Prochaines étapes selon l'environnement:\"\necho \"\"\necho \"  LOCAL:\"\necho \"    npm run dev\"\necho \"    → Puis ouvrir http://localhost:3000\"\necho \"\"\necho \"  PREVIEW (Vercel):\"\necho \"    git push origin version/1.0-supabase-boutique\"\necho \"    → Attendre déploiement Vercel Preview\"\necho \"    → Tester end-to-end en Preview\"\necho \"\"\necho \"  PRODUCTION:\"\necho \"    git checkout main\"\necho \"    git merge version/1.0-supabase-boutique\"\necho \"    git push origin main\"\necho \"    → Déploiement automatique sur Vercel\"\necho \"\"\n\necho \"Documentation:\"\necho \"  - Configuration SMTP: docs/smtp-setup.md\"\necho \"  - Rapport complet: docs/completion-report.md\"\necho \"  - Checklist conception: docs/checklist-conception.md\"\necho \"\"\nprint_success \"Script de déploiement terminé!\"\n